// 4. Item Detail & Camera Component
const ItemDetail = ({ item, onBack, onUpdateItem }: { item: Item, onBack: () => void, onUpdateItem: (updated: Item) => void }) => {
    const [isCameraOpen, setIsCameraOpen] = useState(false);
    const [analyzing, setAnalyzing] = useState(false);
    const [includeMetadata, setIncludeMetadata] = useState(true);
    const [analysisMessage, setAnalysisMessage] = useState<string | null>(null);
    const videoRef = useRef<HTMLVideoElement>(null);
    const fileInputRef = useRef<HTMLInputElement>(null);

    const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
        if (e.target.files && e.target.files[0]) {
            processImage(e.target.files[0]);
        }
    };

    const processImage = async (file: File) => {
        setAnalyzing(true);
        setAnalysisMessage(null);

        const reader = new FileReader();
        reader.onloadend = async () => {
            const base64 = reader.result as string;
            const cleanBase64 = base64.split(',')[1];

            // 1. Analyze with Gemini
            const result = await analyzeImage(cleanBase64, item.name, item.requiredQuantity);

            // 2. Prepare new photo object
            const newPhoto: Photo = {
                id: Date.now().toString(),
                url: base64,
                isVerified: result.match,
                hasWarning: result.discrepancy,
                timestamp: includeMetadata ? new Date().toLocaleString() : undefined,
                coords: includeMetadata ? "lat:-23.55, long:-46.63" : undefined // Mock coords
            };

            // 3. Logic for Warning/Success
            const currentTotal = item.photos.length + 1 + (result.count - 1); // Simple logic approximation

            let userConfirmed = true;

            if (result.discrepancy) {
                 userConfirmed = window.confirm(`Atenção: A IA identificou ${result.count} itens, mas são necessários ${item.requiredQuantity}. Motivo: ${result.reason}. Deseja incluir assim mesmo?`);
            } else if (result.count < item.requiredQuantity && item.photos.length + result.count < item.requiredQuantity) {
                 alert(`Ainda faltam itens. A IA contou ${result.count}. Por favor inclua mais fotos.`);
            }

            if (userConfirmed) {
                // Mock Saving to SharePoint
                console.log("Saving to SharePoint folder: /Eventos/" + item.name + "/", newPhoto);

                const updatedPhotos = [...item.photos, newPhoto];
                const newStatus: ItemStatus = updatedPhotos.length >= 1 ? (updatedPhotos.length >= item.requiredQuantity ? 'Análise' : 'Pendente') : 'Pendente';

                onUpdateItem({
                    ...item,
                    photos: updatedPhotos,
                    status: newStatus
                });
            }

            setAnalyzing(false);
            setIsCameraOpen(false);
        };
        reader.readAsDataURL(file);
    };

    const handleFinishItem = () => {
        if (confirm("Deseja encerrar este item? O relatório será gerado.")) {
            onUpdateItem({ ...item, status: 'Concluído' });
            onBack();
        }
    };

    return (
        <div className="min-h-screen bg-white flex flex-col">
            <header className="bg-white border-b border-slate-200 sticky top-0 z-20 px-4 py-4 flex items-center gap-4">
                <button onClick={onBack} className="p-2 rounded-full hover:bg-slate-100">
                    <span className="material-symbols-outlined text-slate-600">arrow_back</span>
                </button>
                <div className="flex-1">
                    <h2 className="text-lg font-bold text-slate-900">{item.name}</h2>
                    <span className={`text-[10px] uppercase font-bold px-2 py-0.5 rounded ${item.status === 'Concluído' ? 'bg-green-100 text-green-700' : 'bg-slate-100 text-slate-600'}`}>
                        {item.status}
                    </span>
                </div>
            </header>

            <div className="flex-1 p-6 overflow-y-auto">
                <div className="bg-slate-50 p-4 rounded-lg border border-slate-200 mb-6">
                    <h4 className="text-sm font-bold text-slate-800 mb-2">Descrição da Demanda</h4>
                    <p className="text-sm text-slate-600 mb-4">{item.description}</p>
                    <div className="flex justify-between items-center text-xs font-medium text-slate-500 bg-white p-3 rounded border border-slate-200">
                         <span>Necessário: {item.requiredQuantity}</span>
                         <span>Atual: {item.photos.length}</span>
                    </div>
                </div>

                <div className="mb-6">
                     <label className="flex items-center gap-3 p-3 border border-slate-200 rounded-lg cursor-pointer hover:bg-slate-50">
                        <input 
                            type="checkbox" 
                            checked={includeMetadata} 
                            onChange={(e) => setIncludeMetadata(e.target.checked)}
                            className="w-5 h-5 text-slate-800 rounded focus:ring-slate-800 border-gray-300"
                        />
                        <span className="text-sm text-slate-700">Incluir Data e Localização na foto</span>
                     </label>
                </div>

                <div className="grid grid-cols-2 gap-3 mb-24">
                    {item.photos.map((photo, idx) => (
                        <div key={photo.id} className="relative aspect-square rounded-lg overflow-hidden border border-slate-200 shadow-sm">
                            <img src={photo.url} className="w-full h-full object-cover" alt={`Evidence ${idx}`} />
                            {photo.hasWarning && (
                                <div className="absolute top-1 right-1 bg-amber-500 text-white rounded-full p-1">
                                    <span className="material-symbols-outlined text-xs">warning</span>
                                </div>
                            )}
                            {photo.timestamp && (
                                <div className="absolute bottom-0 left-0 right-0 bg-black/60 p-1 text-[8px] text-white truncate">
                                    {photo.timestamp}
                                </div>
                            )}
                        </div>
                    ))}

                    <button 
                        onClick={() => fileInputRef.current?.click()}
                        className="aspect-square rounded-lg border-2 border-dashed border-slate-300 flex flex-col items-center justify-center gap-2 hover:bg-slate-50 hover:border-slate-400 transition-colors"
                    >
                        {analyzing ? (
                             <span className="material-symbols-outlined animate-spin text-slate-400">autorenew</span>
                        ) : (
                             <>
                                <span className="material-symbols-outlined text-slate-400 text-3xl">add_a_photo</span>
                                <span className="text-xs font-semibold text-slate-500">Adicionar</span>
                             </>
                        )}
                    </button>
                    <input 
                        type="file" 
                        ref={fileInputRef} 
                        className="hidden" 
                        accept="image/*" 
                        capture="environment"
                        onChange={handleFileUpload}
                    />
                </div>
            </div>

            <div className="fixed bottom-0 left-0 w-full p-4 bg-white border-t border-slate-200">
                <button 
                    onClick={handleFinishItem}
                    disabled={item.photos.length === 0}
                    className="w-full bg-slate-800 text-white font-bold py-4 rounded-lg shadow-lg disabled:opacity-50 disabled:cursor-not-allowed hover:bg-slate-900 transition-colors"
                >
                    Gerar Relatório e Encerrar Item
                </button>
            </div>
        </div>
    );
};

