const ItemDetail = ({ item, onBack, onUpdateItem }: { item: Item, onBack: () => void, onUpdateItem: (updated: Item) => void }) => {
    const [isCameraOpen, setIsCameraOpen] = useState(false);
    const [analyzing, setAnalyzing] = useState(false);
    const [includeMetadata, setIncludeMetadata] = useState(true);
    const [analysisMessage, setAnalysisMessage] = useState<string | null>(null);
    const videoRef = useRef<HTMLVideoElement>(null);
    const fileInputRef = useRef<HTMLInputElement>(null);

    const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
        if (e.target.files && e.target.files[0]) {
            processImage(e.target.files[0]);
        }
    };

    const processImage = async (file: File) => {
        setAnalyzing(true);
        setAnalysisMessage(null);

        const reader = new FileReader();
        reader.onloadend = async () => {
            const base64 = reader.result as string;
            const cleanBase64 = base64.split(',')[1];

            // 1. Analyze with Gemini
            const result = await analyzeImage(cleanBase64, item.name, item.requiredQuantity);

            // 2. Prepare new photo object
            const newPhoto: Photo = {
                id: Date.now().toString(),
                url: base64,
                isVerified: result.match,
                hasWarning: result.discrepancy,
                timestamp: includeMetadata ? new Date().toLocaleString() : undefined,
                coords: includeMetadata ? "lat:-23.55, long:-46.63" : undefined // Mock coords
            };

            // 3. Logic for Warning/Success
            const currentTotal = item.photos.length + 1 + (result.count - 1); // Simple logic approximation

            let userConfirmed = true;

            if (result.discrepancy) {
                 userConfirmed = window.confirm(`Atenção: A IA identificou ${result.count} itens, mas são necessários ${item.requiredQuantity}. Motivo: ${result.reason}. Deseja incluir assim mesmo?`);
            } else if (result.count < item.requiredQuantity && item.photos.length + result.count < item.requiredQuantity) {
                 alert(`Ainda faltam itens. A IA contou ${result.count}. Por favor inclua mais fotos.`);
            }

            if (userConfirmed) {
                // Mock Saving to SharePoint
                console.log("Saving to SharePoint folder: /Eventos/" + item.name + "/", newPhoto);

                const updatedPhotos = [...item.photos, newPhoto];
                const newStatus: ItemStatus = updatedPhotos.length >= 1 ? (updatedPhotos.length >= item.requiredQuantity ? 'Análise' : 'Pendente') : 'Pendente';

                onUpdateItem({
                    ...item,
                    photos: updatedPhotos,
                    status: newStatus
                });
            }

            setAnalyzing(false);
            setIsCameraOpen(false);
        };
        reader.readAsDataURL(file);
    };

    const handleFinishItem = () => {
        if (confirm("Deseja encerrar este item? O relatório será gerado.")) {
            onUpdateItem({ ...item, status: 'Concluído' });
            onBack();
        }
